results = []


def check(ok, label):
    results.append(("PASS" if ok else "FAIL") + "  " + label)
    return ok


def can_import(name):
    try:
        __import__(name)
        return True
    except ImportError:
        return False


def count_rows(path):
    with open(path, encoding="utf-8") as f:
        return len(f.read().splitlines()) - 1


check(can_import("json"), "package json")
check(can_import("jupyterlab_missing"), "package jupyterlab_missing")
check(count_rows("orders.csv") == 6, "orders.csv has 6 rows")

for line in results:
    print(line)
print(sum(r.startswith("PASS") for r in results), "passed")
